const cust = await api.get("/customers", {});
const mails = await api.get("/mails", {});
const delayed = cust.items.filter(c => c.order && c.order.status === "delayed");
const complaintMails = mails.items.filter(m => m.label === "complaint");
const result = delayed.filter(c => complaintMails.some(m => m.customer_id === c.id)).map(c => c.id);
return { totalCustomers: cust.count, totalMails: mails.count, delayedCount: delayed.length, complaintCount: complaintMails.length, result };
